#!/usr/bin/env python3
"""Fill training_feedback_template.hwpx using training_feedback.json.

Outputs: /root/training_feedback_ready.hwpx

Key behaviors (per task contract):
- Replace {{...}} placeholders in XML files under Contents/.
- 참석자수: digits-only, with Korean number-word fallback.
- 만족도: X.X점 (5.0점 만점)
- 종합의견: append ' 후속 심화반 검토 요망.' (exactly one leading space unless original ends with space)
- Handle placeholders split across multiple text runs within the same paragraph by concatenating adjacent runs.
- After any paragraph text replacement, remove layout-cache elements within that paragraph whose local-name contains 'lineSeg'/'lineSegArray' (case-insensitive).
- Preserve ZIP entry compression types/metadata as much as zipfile allows.
"""

from __future__ import annotations

import json
import os
import re
import shutil
import sys
import zipfile

# Prefer lxml if available (better namespace/parent handling), else fall back.
try:
    from lxml import etree as XET  # type: ignore
    HAVE_LXML = True
except Exception:
    XET = None
    HAVE_LXML = False

import xml.etree.ElementTree as ET

HP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"


def localname(tag: str) -> str:
    if tag is None:
        return ""
    if "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def parse_score_to_float(v) -> float:
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        # e.g., "4.5/5.0" or "4.5" or "4.5점"
        m = re.search(r"([0-9]+(?:\.[0-9]+)?)", v)
        if m:
            return float(m.group(1))
    raise ValueError(f"Unable to parse 만족도 as numeric from: {v!r}")


_SINO_DIGITS = {
    "영": 0,
    "공": 0,
    "일": 1,
    "이": 2,
    "삼": 3,
    "사": 4,
    "오": 5,
    "육": 6,
    "칠": 7,
    "팔": 8,
    "구": 9,
}
_SINO_UNITS = {
    "십": 10,
    "백": 100,
    "천": 1000,
    "만": 10000,
}


def parse_sino_korean_number_word(s: str) -> int | None:
    """Parse numbers like '삼십이', '이백오십', '만이천삼백'."""
    if not s:
        return None
    # Quick reject if it contains chars we don't know.
    for ch in s:
        if ch not in _SINO_DIGITS and ch not in _SINO_UNITS:
            return None

    total = 0
    current = 0
    last_unit = 1

    def flush_current(mult: int):
        nonlocal total, current
        if current == 0:
            current = 1
        total += current * mult
        current = 0

    for ch in s:
        if ch in _SINO_DIGITS:
            current = current * 10 + _SINO_DIGITS[ch] if last_unit == 1 else _SINO_DIGITS[ch]
            last_unit = 1
        else:
            unit = _SINO_UNITS[ch]
            if unit == 10000:
                # 만 acts as section multiplier
                section = (total + current) or 1
                total = section * 10000
                current = 0
                last_unit = unit
                continue
            flush_current(unit)
            last_unit = unit

    return total + current


_NATIVE_UNITS = {
    "한": 1,
    "하나": 1,
    "두": 2,
    "둘": 2,
    "세": 3,
    "셋": 3,
    "네": 4,
    "넷": 4,
    "다섯": 5,
    "여섯": 6,
    "일곱": 7,
    "여덟": 8,
    "아홉": 9,
}
_NATIVE_TENS = {
    "열": 10,
    "스물": 20,
    "스무": 20,
    "서른": 30,
    "마흔": 40,
    "쉰": 50,
    "예순": 60,
    "일흔": 70,
    "여든": 80,
    "아흔": 90,
}


def parse_native_korean_1_to_99(s: str) -> int | None:
    """Parse native Korean numbers up to 99 like '스물다섯', '서른둘', '열한'."""
    if not s:
        return None

    # direct unit
    if s in _NATIVE_UNITS:
        return _NATIVE_UNITS[s]

    # direct ten
    if s in _NATIVE_TENS:
        return _NATIVE_TENS[s]

    # handle '열한/열두/열세/열네' forms
    if s.startswith("열"):
        rest = s[len("열") :]
        if rest in _NATIVE_UNITS:
            return 10 + _NATIVE_UNITS[rest]
        # '열한' uses '한' not '하나'
        if rest == "한":
            return 11

    # general tens + ones
    for ten_word, ten_val in sorted(_NATIVE_TENS.items(), key=lambda kv: -len(kv[0])):
        if s.startswith(ten_word):
            rest = s[len(ten_word) :]
            if not rest:
                return ten_val
            if rest in _NATIVE_UNITS:
                return ten_val + _NATIVE_UNITS[rest]
    return None


def attendees_to_digits(value) -> str:
    """Convert 참석자수 into digits-only string."""
    if value is None:
        raise ValueError("참석자수 is missing")

    s = str(value).strip()
    digits = re.findall(r"\d+", s)
    if digits:
        return "".join(digits)

    # Try Korean number words
    s2 = re.sub(r"\s+", "", s)
    s2 = s2.replace("명", "")

    n = parse_sino_korean_number_word(s2)
    if n is not None:
        return str(n)

    n = parse_native_korean_1_to_99(s2)
    if n is not None:
        return str(n)

    raise ValueError(f"Unable to convert 참석자수 to digits from: {value!r}")


def overall_opinion_with_suffix(value) -> str:
    base = "" if value is None else str(value)
    if not base.endswith(" "):
        base = base + " "
    return base + "후속 심화반 검토 요망."


PLACEHOLDER_RE = re.compile(r"\{\{([^{}]+)\}\}")


def build_replacement_map(data: dict) -> dict[str, str]:
    repl: dict[str, str] = {}

    # Copy all keys by default, then override with transformations.
    for k, v in data.items():
        repl[f"{{{{{k}}}}}"] = "" if v is None else str(v)

    # 참석자수 transform
    if "참석자수" in data:
        repl["{{참석자수}}"] = attendees_to_digits(data["참석자수"])

    # 만족도 transform
    if "만족도" in data:
        score = parse_score_to_float(data["만족도"])
        repl["{{만족도}}"] = f"{score:.1f}점 (5.0점 만점)"

    # 종합의견 transform
    if "종합의견" in data:
        repl["{{종합의견}}"] = overall_opinion_with_suffix(data["종합의견"])

    return repl


def remove_layout_caches(elem) -> int:
    """Remove layout-cache elements inside elem.

    Returns number removed.
    """

    def is_cache_tag(tag: str) -> bool:
        ln = localname(tag).lower()
        return ("lineseg" in ln) or ("linesegarray" in ln) or ("lineseg" in ln)

    removed = 0

    # ElementTree / lxml compatible recursive removal by iterating over a copy of children
    for child in list(elem):
        if is_cache_tag(child.tag):
            elem.remove(child)
            removed += 1
        else:
            removed += remove_layout_caches(child)
    return removed


def xml_replace_placeholders(xml_bytes: bytes, repl: dict[str, str], filename: str) -> tuple[bytes, dict]:
    """Replace placeholders in XML bytes and remove layout caches for modified paragraphs."""

    # Parse XML
    if HAVE_LXML:
        parser = XET.XMLParser(resolve_entities=False, remove_blank_text=False, recover=False)
        root = XET.fromstring(xml_bytes, parser=parser)

        def tostring(node) -> bytes:
            return XET.tostring(node, encoding="utf-8", xml_declaration=True)

        def iter_paragraphs():
            # paragraphs are hp:p
            return root.iterfind(f".//{{{HP_NS}}}p")

        def iter_t_elems(p):
            for t in p.iterfind(f".//{{{HP_NS}}}t"):
                yield t

    else:
        ET.register_namespace("hp", HP_NS)
        root = ET.fromstring(xml_bytes)

        def tostring(node) -> bytes:
            return ET.tostring(node, encoding="utf-8", xml_declaration=True)

        def iter_paragraphs():
            return root.iterfind(f".//{{{HP_NS}}}p")

        def iter_t_elems(p):
            return p.iterfind(f".//{{{HP_NS}}}t")

    # Collect placeholders in this file (for diagnostics)
    stats = {
        "filename": filename,
        "paragraphs_modified": 0,
        "layout_cache_elements_removed": 0,
        "placeholders_seen": [],
        "placeholders_replaced": [],
    }

    for p in iter_paragraphs():
        t_elems = list(iter_t_elems(p))
        if not t_elems:
            continue

        combined = "".join((t.text or "") for t in t_elems)
        if "{{" not in combined:
            continue

        seen = [f"{{{{{m.group(1)}}}}}" for m in PLACEHOLDER_RE.finditer(combined)]
        if seen:
            stats["placeholders_seen"].extend(seen)

        new_text = combined
        changed = False
        for ph, val in repl.items():
            if ph in new_text:
                new_text = new_text.replace(ph, val)
                changed = True
                stats["placeholders_replaced"].append(ph)

        # If no replacement happened but placeholders exist, it's likely missing data.
        if "{{" in combined and not changed:
            unknown = sorted(set(seen) - set(repl.keys()))
            raise KeyError(
                f"Found placeholders in {filename} paragraph id={p.get('id')} but no replacements applied. "
                f"Unknown placeholders: {unknown}"
            )

        if changed:
            t_elems[0].text = new_text
            for t in t_elems[1:]:
                t.text = ""

            stats["paragraphs_modified"] += 1
            stats["layout_cache_elements_removed"] += remove_layout_caches(p)

    out = tostring(root)
    return out, stats


def copy_zip_preserve_entries(src_zip: str, dst_zip: str, repl: dict[str, str]) -> list[dict]:
    """Read src_zip and write dst_zip with modified XML entries."""

    stats_all: list[dict] = []
    with zipfile.ZipFile(src_zip, "r") as zin:
        with zipfile.ZipFile(dst_zip, "w") as zout:
            for info in zin.infolist():
                data = zin.read(info.filename)

                new_data = data
                if info.filename.lower().endswith(".xml") and b"{{" in data:
                    try:
                        new_data, st = xml_replace_placeholders(data, repl, info.filename)
                        stats_all.append(st)
                    except Exception as e:
                        raise RuntimeError(f"XML replacement failed for {info.filename}: {e}") from e

                zi = zipfile.ZipInfo(info.filename)
                zi.date_time = info.date_time
                zi.compress_type = info.compress_type
                zi.comment = info.comment
                zi.extra = info.extra
                zi.internal_attr = info.internal_attr
                zi.external_attr = info.external_attr
                zi.create_system = info.create_system
                zi.flag_bits = info.flag_bits

                # Note: zipfile does not expose all metadata round-trip perfectly.
                zout.writestr(zi, new_data)

    return stats_all


def main() -> int:
    template_path = "/root/training_feedback_template.hwpx"
    json_path = "/root/training_feedback.json"
    output_path = "/root/training_feedback_ready.hwpx"

    if not os.path.exists(template_path):
        print(f"Missing template: {template_path}", file=sys.stderr)
        return 2
    if not os.path.exists(json_path):
        print(f"Missing JSON: {json_path}", file=sys.stderr)
        return 2

    with open(json_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    print("JSON key-value pairs:")
    for k in sorted(data.keys()):
        print(f"- {k}: {data[k]}")

    repl = build_replacement_map(data)

    # Explicitly show the transformed fields
    print("\nTransformed fields:")
    if "{{참석자수}}" in repl:
        print(f"- 참석자수 => {repl['{{참석자수}}']}")
    if "{{만족도}}" in repl:
        print(f"- 만족도 => {repl['{{만족도}}']}")
    if "{{종합의견}}" in repl:
        print(f"- 종합의견 => {repl['{{종합의견}}']}")

    # Step 5.1: copy template to output
    shutil.copyfile(template_path, output_path)

    # Modify by rewriting to a temp zip then replace
    tmp_path = output_path + ".tmp"
    stats = copy_zip_preserve_entries(output_path, tmp_path, repl)
    os.replace(tmp_path, output_path)

    print("\nReplacement stats (files modified):")
    for st in stats:
        print(
            f"- {st['filename']}: paragraphs_modified={st['paragraphs_modified']}, "
            f"layout_cache_removed={st['layout_cache_elements_removed']}, "
            f"placeholders_seen={len(st['placeholders_seen'])}, replaced={len(set(st['placeholders_replaced']))}"
        )

    # Step 6 validation
    with zipfile.ZipFile(output_path, "r") as z:
        bad = z.testzip()
        assert bad is None, f"Corrupt entry: {bad}"
        for info in z.infolist():
            data = z.read(info.filename)
            try:
                text = data.decode("utf-8")
            except Exception:
                continue
            assert "{{" not in text and "}}" not in text, f"Placeholder remains in {info.filename}"

    print("\nAll checks passed.")

    # Step 7: print XML text content for visual confirmation
    print("\n===== Output XML contents (for visual verification) =====")
    with zipfile.ZipFile(output_path, "r") as z:
        for name in z.namelist():
            if name.lower().endswith(".xml") and name.startswith("Contents/"):
                print("\n" + "=" * 80)
                print(name)
                print("=" * 80)
                data = z.read(name)
                try:
                    print(data.decode("utf-8"))
                except Exception:
                    print(data.decode("utf-8", "replace"))

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

