                changed = True
                stats["placeholders_replaced"].append(ph)

        # If no replacement happened but placeholders exist, it's likely missing data.
        if "{{" in combined and not changed:
            unknown = sorted(set(seen) - set(repl.keys()))
            raise KeyError(
                f"Found placeholders in {filename} paragraph id={p.get('id')} but no replacements applied. "
                f"Unknown placeholders: {unknown}"
            )

        if changed:
            t_elems[0].text = new_text
            for t in t_elems[1:]:
                t.text = ""

            stats["paragraphs_modified"] += 1
            stats["layout_cache_elements_removed"] += remove_layout_caches(p)

    out = tostring(root)
    return out, stats


def copy_zip_preserve_entries(src_zip: str, dst_zip: str, repl: dict[str, str]) -> list[dict]:
    """Read src_zip and write dst_zip with modified XML entries."""

    stats_all: list[dict] = []
    with zipfile.ZipFile(src_zip, "r") as zin:
        with zipfile.ZipFile(dst_zip, "w") as zout:
            for info in zin.infolist():
                data = zin.read(info.filename)

                new_data = data
                if info.filename.lower().endswith(".xml") and b"{{" in data:
                    try:
                        new_data, st = xml_replace_placeholders(data, repl, info.filename)
                        stats_all.append(st)
                    except Exception as e:
                        raise RuntimeError(f"XML replacement failed for {info.filename}: {e}") from e

                zi = zipfile.ZipInfo(info.filename)
                zi.date_time = info.date_time
                zi.compress_type = info.compress_type
                zi.comment = info.comment
                zi.extra = info.extra
                zi.internal_attr = info.internal_attr
                zi.external_attr = info.external_attr
                zi.create_system = info.create_system
                zi.flag_bits = info.flag_bits

                # Note: zipfile does not expose all metadata round-trip perfectly.
                zout.writestr(zi, new_data)

    return stats_all


def main() -> int:
    template_path = "/root/training_feedback_template.hwpx"
    json_path = "/root/training_feedback.json"
    output_path = "/root/training_feedback_ready.hwpx"

    if not os.path.exists(template_path):
        print(f"Missing template: {template_path}", file=sys.stderr)
        return 2
    if not os.path.exists(json_path):
        print(f"Missing JSON: {json_path}", file=sys.stderr)
        return 2

    with open(json_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    print("JSON key-value pairs:")
    for k in sorted(data.keys()):
        print(f"- {k}: {data[k]}")

    repl = build_replacement_map(data)

    # Explicitly show the transformed fields
    print("\nTransformed fields:")
    if "{{참석자수}}" in repl:
        print(f"- 참석자수 => {repl['{{참석자수}}']}")
    if "{{만족도}}" in repl:
        print(f"- 만족도 => {repl['{{만족도}}']}")
    if "{{종합의견}}" in repl:
        print(f"- 종합의견 => {repl['{{종합의견}}']}")

    # Step 5.1: copy template to output
    shutil.copyfile(template_path, output_path)

    # Modify by rewriting to a temp zip then replace
    tmp_path = output_path + ".tmp"
    stats = copy_zip_preserve_entries(output_path, tmp_path, repl)
    os.replace(tmp_path, output_path)

    print("\nReplacement stats (files modified):")
    for st in stats:
        print(
            f"- {st['filename']}: paragraphs_modified={st['paragraphs_modified']}, "
            f"layout_cache_removed={st['layout_cache_elements_removed']}, "
            f"placeholders_seen={len(st['placeholders_seen'])}, replaced={len(set(st['placeholders_replaced']))}"
        )

    # Step 6 validation
    with zipfile.ZipFile(output_path, "r") as z:
        bad = z.testzip()
        assert bad is None, f"Corrupt entry: {bad}"
        for info in z.infolist():
            data = z.read(info.filename)
            try:
                text = data.decode("utf-8")
            except Exception:
                continue
            assert "{{" not in text and "}}" not in text, f"Placeholder remains in {info.filename}"

    print("\nAll checks passed.")

    # Step 7: print XML text content for visual confirmation
    print("\n===== Output XML contents (for visual verification) =====")
    with zipfile.ZipFile(output_path, "r") as z:
        for name in z.namelist():
            if name.lower().endswith(".xml") and name.startswith("Contents/"):
                print("\n" + "=" * 80)
                print(name)
                print("=" * 80)
                data = z.read(name)
                try:
                    print(data.decode("utf-8"))
                except Exception:
                    print(data.decode("utf-8", "replace"))

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
